  const pts = []; for (let k = 0; k < 32; k++) { const a = k * Math.PI / 16, r = k % 2 ? 39.5 : 43; pts.push((50 + r * Math.cos(a)).toFixed(1) + ',' + (48 + r * Math.sin(a)).toFixed(1)); }
  let o = `<svg width="${size}" height="${Math.round(size * 1.12)}" viewBox="0 0 100 112" aria-hidden="true" class="medal"><defs><linearGradient id="${g}m" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="${m1}"/><stop offset=".5" stop-color="${m2}"/><stop offset="1" stop-color="${m3}"/></linearGradient><radialGradient id="${g}e" cx="40%" cy="35%" r="70%"><stop offset="0" stop-color="${e1}"/><stop offset="1" stop-color="${e2}"/></radialGradient></defs>`;
  o += `<path d="M36 64 L24 106 L35 99 L44 108 L52 70Z" fill="${rib1}" stroke="${rib2}" stroke-width="1.6" stroke-linejoin="round"/><path d="M64 64 L76 106 L65 99 L56 108 L48 70Z" fill="${rib1}" stroke="${rib2}" stroke-width="1.6" stroke-linejoin="round"/>`;
  o += `<polygon points="${pts.join(' ')}" fill="url(#${g}m)" stroke="${m3}" stroke-width="1.6" stroke-linejoin="round"/><circle cx="50" cy="48" r="33" fill="${m3}" opacity=".55"/><circle cx="50" cy="48" r="30" fill="url(#${g}e)" stroke="${m1}" stroke-width="2"/>`;
  o += `<g transform="translate(27.2 25.2) scale(1.9)"><path d="${glyph}" fill="none" stroke="#000" stroke-opacity=".22" stroke-width="2.8" stroke-linecap="round" stroke-linejoin="round" transform="translate(.5 .8)"/><path d="${glyph}" fill="none" stroke="${gl}" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/></g>`;
